package net.officefloor.hq.app.setting;

/** The settings form as submitted: the clerk limit (blank: no limit), the floor (blank: 1.00) and the terms in
 *  days (blank: 14) and the late percent
 *  (blank: 0.00) and the policy date (YYYY-MM-DD; blank: the sheet's today) and the period numbering from (YYYY-MM-DD; blank: off) and the terms of grades A, B and C in days (blank: the sheet's terms) and the cap (blank: none) and the proof threshold (blank: none); and the permission matrix entries for open, settle, void, reassign, close and reopen
 *  (comma separated roles; blank: the standing rule); and the grace days (a whole number of days; blank: off; not dated); and the note threshold (blank: none); and the entry date (YYYY-MM-DD; blank: off; not dated); and the grace days of grades A, B and C (blank: none); and the proof thresholds of grades A, B and C (blank: none — the sheet's applies); and the pot (two decimals; blank: none; not dated); and the parent sheet (a sheet's id; blank: none; not dated); and the fiscal year start month (1 to 12; blank: 1; not dated); and the alert threshold (two decimals; blank: off; not dated); and the rounding mode (half-up or half-even; blank: none — a claim rounds by the policy date); and the review threshold (blank: none); and the escalation gap (a whole number of days; blank: off; not dated); and the review SLA (a whole number of days; blank: none; not dated); and the proof kinds (a comma separated list of receipt and photo; blank: none; not dated); and the default grade (A, B or C; blank: A; not dated); and the clerk limits of grades A, B and C (blank: none — the sheet's applies); and the maximum of open claims per person (a whole number, 0 or more; blank: none; not dated); a key left out (null) is not changed.
 *  Each setting that carries a figure has its from-date (YYYY-MM-DD; blank or left out: the sheet's today): it is
 *  recorded from that date on. */
public record SettingsRequest(String clerkLimit, String floor, String terms, String latePct, String policyDate, String periodNumberingFrom,
        String termsA, String termsB, String termsC, String cap, String proofThreshold,
        String clerkLimitFrom, String floorFrom, String termsFrom, String latePctFrom,
        String termsAFrom, String termsBFrom, String termsCFrom, String capFrom, String proofThresholdFrom,
        String permOpen, String permSettle, String permVoid, String permReassign, String permClose, String permReopen,
        String graceDays, String noteThreshold, String noteThresholdFrom, String entryDate,
        String graceA, String graceB, String graceC, String graceAFrom, String graceBFrom, String graceCFrom,
        String proofThresholdA, String proofThresholdB, String proofThresholdC,
        String proofThresholdAFrom, String proofThresholdBFrom, String proofThresholdCFrom, String pot, String parent,
        String fiscalStartMonth, String alertThreshold, String rounding, String roundingFrom,
        String reviewThreshold, String reviewThresholdFrom, String escalateAfter, String reviewSla, String proofKinds, String defaultGrade,
        String clerkLimitA, String clerkLimitB, String clerkLimitC,
        String clerkLimitAFrom, String clerkLimitBFrom, String clerkLimitCFrom, String scoreMid, String scoreHigh, String scoreLog, String maxOpen) {
}
package net.officefloor.hq.app.setting;

import java.time.LocalDate;
import net.officefloor.hq.app.sheet.SettingLog;
import net.officefloor.hq.app.sheet.SettingLogRepository;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.plugin.variable.Val;

/** Sets the settings the form sets: a setting that carries a figure (the clerk limit, floor, terms, late percent,
 *  each grade's own terms, cap, proof threshold, note threshold, each grade's grace days, each grade's proof threshold, review threshold) is recorded from its from-date (the sheet's today when none is given), replacing a
 *  value recorded from that date and keeping the others; the policy date, period numbering from and entry date are set; a permission matrix entry
 *  (key perm-<action>), the grace days, the pot, the parent sheet, the fiscal year start month and the alert threshold and the escalation gap and the maximum of open claims and the review SLA and the proof kinds and the default grade and the score thresholds are recorded undated. Each is logged with the sheet's today (so the
 *  settings can be worked out as they stood on an earlier date). */
public class ApplySettings {
    public void apply(@Val SettingsInput input, @Val Sheet sheet, SheetRepository repository, SettingLogRepository log) {
        for (SettingsInput.Change change : input.changes()) {
            LocalDate from = null;
            if (change.dated()) {
                from = change.from() != null ? change.from() : sheet.getToday();
                sheet.record(change.key(), from, change.value());
            } else if (change.key().startsWith("perm-") || Sheet.GRACE_DAYS.equals(change.key())
                    || Sheet.ESCALATE_AFTER.equals(change.key()) || Sheet.MAX_OPEN.equals(change.key()) || Sheet.REVIEW_SLA.equals(change.key())
                    || Sheet.PROOF_KINDS.equals(change.key()) || Sheet.DEFAULT_GRADE.equals(change.key())
                    || Sheet.POT.equals(change.key()) || Sheet.PARENT.equals(change.key())
                    || Sheet.FISCAL_START_MONTH.equals(change.key())
                    || Sheet.ALERT_THRESHOLD.equals(change.key())
                    || Sheet.SCORE_MID.equals(change.key()) || Sheet.SCORE_HIGH.equals(change.key())
                    || Sheet.SCORE_LOG.equals(change.key())) {
                sheet.record(change.key(), null, change.value());
            } else if (Sheet.POLICY_DATE.equals(change.key())) {
                sheet.setPolicyDate(change.value() == null ? null : LocalDate.parse(change.value()));
            } else if (Sheet.PERIOD_NUMBERING_FROM.equals(change.key())) {
                sheet.setPeriodNumberingFrom(change.value() == null ? null : LocalDate.parse(change.value()));
            } else if (Sheet.ENTRY_DATE.equals(change.key())) {
                sheet.setEntryDate(change.value() == null ? null : LocalDate.parse(change.value()));
            } else {
                continue;
            }
            log.save(new SettingLog(sheet.getId(), change.key(), from, change.value(), sheet.getToday()));
            parent(changes, request.parent());
            fiscalStartMonth(changes, request.fiscalStartMonth());
            undatedAmount(changes, Sheet.ALERT_THRESHOLD, request.alertThreshold(),
                    "The alert threshold must be an amount, 0.00 or more, with up to two decimals, or blank.");
            rounding(changes, request.rounding(), request.roundingFrom());
            amount(changes, Sheet.REVIEW_THRESHOLD, request.reviewThreshold(), null, request.reviewThresholdFrom(),
                    "The review threshold must be an amount, 0.00 or more, with up to two decimals, or blank.");
            undatedDays(changes, Sheet.ESCALATE_AFTER, request.escalateAfter(),
                    "The escalation gap must be a whole number of days, 0 or more, or blank.");
            undatedDays(changes, Sheet.REVIEW_SLA, request.reviewSla(),
                    "The review SLA must be a whole number of days, 0 or more, or blank.");
            proofKinds(changes, request.proofKinds());
            defaultGrade(changes, request.defaultGrade());
            amount(changes, Sheet.clerkLimitKey("A"), request.clerkLimitA(), null, request.clerkLimitAFrom(),
                    "The clerk limit of grade A must be an amount, 0.00 or more, with up to two decimals, or blank.");
            amount(changes, Sheet.clerkLimitKey("B"), request.clerkLimitB(), null, request.clerkLimitBFrom(),
                    "The clerk limit of grade B must be an amount, 0.00 or more, with up to two decimals, or blank.");
            amount(changes, Sheet.clerkLimitKey("C"), request.clerkLimitC(), null, request.clerkLimitCFrom(),
                    "The clerk limit of grade C must be an amount, 0.00 or more, with up to two decimals, or blank.");
            wholeNumber(changes, Sheet.SCORE_MID, request.scoreMid(), "The mid score threshold must be a whole number, or blank.");
            wholeNumber(changes, Sheet.SCORE_HIGH, request.scoreHigh(), "The high score threshold must be a whole number, or blank.");
            if (capped != null) {
                long open = repository.findBySheetIdAndPersonIdOrderByIdDesc(claim.getSheetId(), claim.getPersonId()).stream()
                        .filter(c -> !c.getId().equals(claim.getId()))
                        .filter(c -> c.getStatus() == ClaimStatus.OPEN || c.getStatus() == ClaimStatus.PENDING)
                        .filter(c -> c.getDueBy() != null && capped.contains(c.getDueBy()))
                        .count();
                if (open >= capped.getCap()) {
                    throw new ClaimStatusException("The person already has " + capped.getCap()
                            + " open claims in period " + capped.getName() + ".");
                }
            }
            Integer maxOpen = sheet.getMaxOpen();
            if ("open".equals(action) && maxOpen != null) {
                long open = repository.findBySheetIdAndPersonIdOrderByIdDesc(claim.getSheetId(), claim.getPersonId()).stream()
                        .filter(c -> !c.getId().equals(claim.getId()))
                        .filter(c -> c.getStatus() == ClaimStatus.OPEN || c.getStatus() == ClaimStatus.PENDING)
                        .count();
                if (open >= maxOpen) {
                    throw new ClaimStatusException("The person already has " + maxOpen + " open claims.");
                }
            }
            BigDecimal reviewThreshold = sheet.reviewThresholdOn(claim.getDate());
            if ("open".equals(action) && reviewThreshold != null && due != null && due.compareTo(reviewThreshold) > 0) {
                claim.setStatus(ClaimStatus.REVIEW);
                claim.setReviewOn(sheet.getToday());
                claim.setOpenedBy(user);
                repository.saveAndFlush(claim);
                return null;
            }
            claim.setStatus(next);
            if ("open".equals(action)) {
                claim.setOpenedBy(user);
            }
        } else {
            ClaimStatus next = check(claim, action);
            boolean steward = Role.STEWARD.equals(role);
            if (("approve".equals(action) || "reject".equals(action)) && !steward && !people.findById(claim.getPersonId())
                    .map(p -> user.equals(p.getApprover())).orElse(false)) {
                throw new ClerkLimitException("Only a steward or the person's approver can approve or reject a pending claim.");
            }
            if ("void".equals(action) && claim.getStatus() == ClaimStatus.SETTLED) {
        return max == null ? null : Integer.valueOf(max);
    }

    /** The review SLA: a REVIEW claim whose review day plus this many days is before the sheet's today is late.
     *  Not dated; null when none. */
    public Integer getReviewSla() {
        String days = valueOn(REVIEW_SLA, today);
        return days == null ? null : Integer.valueOf(days);
    }

    /** Whether the score log is on: while it is, changing the sheet's today writes each person's score as it stood
package net.officefloor.hq.app.setting;

import java.math.BigDecimal;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.hq.app.sheet.SheetSetting;

/** The sheet's settings as the screen shows them, each in force on the sheet's today: the clerk limit with two decimals (null: no limit) and the
 *  floor with two decimals, and the terms in days, and the late percent with two decimals, and the policy date (YYYY-MM-DD; "" when
 *  blank: the sheet's today), and the period numbering from (YYYY-MM-DD; "" when off), and the own terms in days of grades A, B and C
 *  ("" when the grade uses the sheet's terms), and the cap with two decimals ("" when there is none), and the proof threshold with two decimals ("" when there is none); and the values recorded
 *  for each dated setting, by key (floor, late-pct, terms, terms-A/B/C, clerk-limit, cap), by from-date; and the permission matrix
 *  entry of each of open, settle, void, reassign, close and reopen (its comma separated roles; "" when blank: the standing rule); and the grace days ("" when off); and the note threshold with two decimals ("" when there is none); and the entry date (YYYY-MM-DD; "" when off); and the grace days of grades A, B and C in force ("" when none); and the proof thresholds of grades A, B and C in force ("" when none); and the pot with two decimals ("" when there is none; not dated); and the parent sheet's id ("" when none; not dated); and the fiscal year start month (1 to 12; not dated); and the alert threshold with two decimals ("" when off; not dated); and the rounding mode in force (half-up or half-even; "" when none); and the review threshold with two decimals ("" when there is none); and the escalation gap in days ("" when off; not dated); and the review SLA in days ("" when none; not dated); and the proof kinds (comma separated; "" when none; not dated); and the default grade ("" when blank, meaning A; not dated); and the clerk limits of grades A, B and C in force ("" when none); and the maximum of open claims per person ("" when none; not dated). */
public record SettingsResponse(String clerkLimit, String floor, String terms, String latePct, String policyDate,
        String periodNumberingFrom, String termsA, String termsB, String termsC, String cap, String proofThreshold,
        Map<String, List<Dated>> dated, String permOpen, String permSettle, String permVoid, String permReassign,
        String permClose, String permReopen, String graceDays, String noteThreshold, String entryDate,
        String graceA, String graceB, String graceC,
        String proofThresholdA, String proofThresholdB, String proofThresholdC, String pot, String parent,
        String fiscalStartMonth, String alertThreshold, String rounding, String reviewThreshold, String escalateAfter, String reviewSla, String proofKinds, String defaultGrade,
        String clerkLimitA, String clerkLimitB, String clerkLimitC, String scoreMid, String scoreHigh, String scoreLog, String maxOpen) {

    /** A value recorded from a date on (null from: the beginning of time; null value: blank). */
    public record Dated(String from, String value) {
    }

    public static SettingsResponse from(Sheet sheet) {
        Map<String, List<Dated>> dated = new LinkedHashMap<>();
        for (SheetSetting s : sheet.getSettings()) {
            dated.computeIfAbsent(s.getKey(), k -> new ArrayList<>())
                    .add(new Dated(s.getFromDate() == null ? null : s.getFromDate().toString(), s.getValue()));
        }
        return new SettingsResponse(sheet.getClerkLimit() == null ? null : sheet.getClerkLimit().toPlainString(),
                sheet.floorOn(sheet.getToday()).setScale(2).toPlainString(), String.valueOf(sheet.termsOn(sheet.getToday())),
                sheet.latePctOn(sheet.getToday()).setScale(2).toPlainString(),
                sheet.getPolicyDate() == null ? "" : sheet.getPolicyDate().toString(),
                sheet.getPeriodNumberingFrom() == null ? "" : sheet.getPeriodNumberingFrom().toString(),
                gradeTerms(sheet, "A"), gradeTerms(sheet, "B"), gradeTerms(sheet, "C"),
                sheet.getCap() == null ? "" : sheet.getCap().toPlainString(),
                sheet.proofThresholdOn(sheet.getToday()) == null ? "" : sheet.proofThresholdOn(sheet.getToday()).toPlainString(),
                dated, sheet.permOf("open"), sheet.permOf("settle"), sheet.permOf("void"), sheet.permOf("reassign"),
                sheet.permOf("close"), sheet.permOf("reopen"),
                sheet.getGraceDays() == null ? "" : String.valueOf(sheet.getGraceDays()),
                sheet.noteThresholdOn(sheet.getToday()) == null ? "" : sheet.noteThresholdOn(sheet.getToday()).toPlainString(),
                sheet.getEntryDate() == null ? "" : sheet.getEntryDate().toString(),
                gradeGrace(sheet, "A"), gradeGrace(sheet, "B"), gradeGrace(sheet, "C"),
                gradeProofThreshold(sheet, "A"), gradeProofThreshold(sheet, "B"), gradeProofThreshold(sheet, "C"),
                sheet.getPot() == null ? "" : sheet.getPot().toPlainString(),
                sheet.getParent() == null ? "" : sheet.getParent(),
                String.valueOf(sheet.getFiscalStartMonth()),
                sheet.getAlertThreshold() == null ? "" : sheet.getAlertThreshold().toPlainString(),
                sheet.roundingOn(sheet.getToday()) == null ? "" : sheet.roundingOn(sheet.getToday()),
                sheet.reviewThresholdOn(sheet.getToday()) == null ? "" : sheet.reviewThresholdOn(sheet.getToday()).toPlainString(),
                sheet.getEscalateAfter() == null ? "" : String.valueOf(sheet.getEscalateAfter()),
                sheet.getReviewSla() == null ? "" : String.valueOf(sheet.getReviewSla()),
                String.join(",", sheet.getProofKinds()),
                sheet.valueOn(Sheet.DEFAULT_GRADE, sheet.getToday()) == null ? "" : sheet.valueOn(Sheet.DEFAULT_GRADE, sheet.getToday()),
                gradeClerkLimit(sheet, "A"), gradeClerkLimit(sheet, "B"), gradeClerkLimit(sheet, "C"),
                scoreThreshold(sheet, Sheet.SCORE_MID), scoreThreshold(sheet, Sheet.SCORE_HIGH),
                sheet.isScoreLog() ? "on" : "",
                sheet.getMaxOpen() == null ? "" : String.valueOf(sheet.getMaxOpen()));
    }

    /** A score threshold (score-mid or score-high); "" when blank. */
    public static String scoreThreshold(Sheet sheet, String key) {
        Integer threshold = sheet.getScoreThreshold(key);
        return threshold == null ? "" : String.valueOf(threshold);
    }

    /** The grade's grace days in force on the sheet's today; "" when it has none. */
    public static String gradeGrace(Sheet sheet, String grade) {
        Integer grace = sheet.gradeGraceOn(grade, sheet.getToday());
        return grace == null ? "" : String.valueOf(grace);
    }

    /** The grade's proof threshold in force on the sheet's today with two decimals; "" when it has none. */
    public static String gradeProofThreshold(Sheet sheet, String grade) {
        BigDecimal threshold = sheet.gradeProofThresholdOn(grade, sheet.getToday());
        return threshold == null ? "" : threshold.toPlainString();
    }

    /** The grade's clerk limit in force on the sheet's today with two decimals; "" when it has none. */
    public static String gradeClerkLimit(Sheet sheet, String grade) {
        BigDecimal limit = sheet.gradeClerkLimitOn(grade, sheet.getToday());
        return limit == null ? "" : limit.toPlainString();
    }

    /** The grade's own terms in days in force on the sheet's today; "" when it uses the sheet's terms. */
    public static String gradeTerms(Sheet sheet, String grade) {
        Integer terms = sheet.gradeTermsOn(grade, sheet.getToday());
        return terms == null ? "" : String.valueOf(terms);
    }
}
package net.officefloor.hq.app.claim;

import java.util.List;

/** A claim as the screen shows it: its amount with two decimals, its date (YYYY-MM-DD) its note, its status, its number (null when it has none)
 * and its due fixed when it was settled (null when it has none), and who opened it (null when never opened);
 * whether its person's last statement binds it, and the figure it binds it to (null: none, or n/a); the number of the
